from __future__ import annotations

from pathlib import Path
from typing import Any, Optional

import polars as pl
import torch

from sglang.srt.debug_utils.dump_loader import ValueWithMeta, filter_rows


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as a simple text table.

    Includes the title (if given) and all column names followed by their values.
    Empty DataFrames (no rows and/or no columns) are handled gracefully.
    """
    lines: list[str] = []
    if title is not None:
        lines.append(title)

    columns: list[str] = df.columns
    if columns:
        lines.append(" | ".join(str(c) for c in columns))
        for row in df.iter_rows():
            lines.append(" | ".join("" if v is None else str(v) for v in row))

    return "\n".join(lines)


def rows_to_text(rows: list[dict[str, Any]], *, title: Optional[str] = None) -> str:
    """Render a list of row dicts as a text table via ``_render_polars_as_text``."""
    return _render_polars_as_text(_rows_to_df(rows), title=title)


def _rows_to_df(rows: list[dict[str, Any]]) -> pl.DataFrame:
    columns: list[str] = []
    for row in rows:
        for key in row:
            if key not in columns:
                columns.append(key)
    normalized: list[dict[str, Any]] = [
        {col: row.get(col) for col in columns} for row in rows
    ]
    return pl.DataFrame(normalized)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Write ``rank/size`` parallel dimension entries from ``info`` into ``row_data``.

    For each ``<base>_rank`` key with a matching ``<base>_size`` key, sets
    ``row_data[<base>] = "{rank}/{size}"``. No-op when ``info`` is empty or
    contains an ``"error"`` key; ``_rank`` keys lacking a ``_size`` are skipped.
    """
    if not info or "error" in info:
        return

    for key in info:
        if not key.endswith("_rank"):
            continue
        base: str = key[: -len("_rank")]
        size_key: str = f"{base}_size"
        if size_key in info:
            row_data[base] = f"{info[key]}/{info[size_key]}"


def _load_meta(dump_dir: Path, row: dict[str, Any]) -> dict[str, Any]:
    filename: Optional[str] = row.get("filename")
    if filename is None:
        return {}
    return ValueWithMeta.load(Path(dump_dir) / filename).meta


def _load_tensor_values(dump_dir: Path, row: Optional[dict[str, Any]]) -> list[Any]:
    if row is None:
        return []
    filename: Optional[str] = row.get("filename")
    if filename is None:
        return []
    value: Any = ValueWithMeta.load(Path(dump_dir) / filename).value
    if value is None:
        return []
    if isinstance(value, torch.Tensor):
        return value.flatten().tolist()
    return list(value)


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect per-rank parallel topology info from ``input_ids`` dump files.

    Returns None if there are no ``input_ids`` rows. Otherwise returns one dict
    per unique rank, each with ``"rank"`` plus any parallel dimension entries
    (e.g. ``"tp": "0/2"``) read from ``sglang_parallel_info`` in file metadata.
    """
    rows: list[dict[str, Any]] = filter_rows(df, {"name": "input_ids"})
    if not rows:
        return None

    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()
    for row in rows:
        rank: Any = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        row_data: dict[str, Any] = {"rank": rank}
        meta: dict[str, Any] = _load_meta(dump_dir, row)
        info = meta.get("sglang_parallel_info")
        if isinstance(info, dict):
